#!/usr/bin/env bash
# Generated by ScrapeSmith (browser build). One command, full pipeline.
set -euo pipefail
cd "$(dirname "$0")"

python3 -c "import playwright, bs4" 2>/dev/null || {
  echo "Missing dependencies. Run: pip install -r requirements.txt && python3 -m playwright install chromium" >&2
  exit 1
}

MAX_PAGES="${MAX_PAGES:-5}"

echo "[1/2] scraping with headless Chromium (max ${MAX_PAGES} pages)"
python3 scraper.py --max-pages "${MAX_PAGES}" --out raw.jsonl --proxies proxies.json

echo "[2/2] mapping"
python3 mapper.py --in raw.jsonl --out mapped.jsonl

echo "done: $(wc -l < mapped.jsonl) records in mapped.jsonl"
